                ['q' => "Можно ли использовать Monica как ИИ-память для ChatGPT или Claude?", 'a' => "У Monica есть руководства по подключению для ChatGPT и Claude, а также для других удалённых MCP-клиентов. Доступные способы подключения и поддерживаемые операции зависят от возможностей, настроек и тарифа вашего ассистента. Инструкции по настройке смотрите в документации MCP."],
                ['q' => "Monica автоматически запоминает всё, что я говорю ассистенту?", 'a' => "Нет. Monica не читает и не отслеживает ваши разговоры. Сведения сохраняются, когда ваш ассистент вызывает инструмент Monica. Вы можете прямо попросить ассистента сохранить что-то в Monica или заглянуть в Monica, отвечая на вопрос. Будет ли он делать это сам, зависит от ассистента."],
                ['q' => "Какие сведения ассистент может сохранить в Monica?", 'a' => "Ассистенты могут создавать поддерживаемые записи: людей по имени, семейные связи, события жизни, напоминания, заметки и списки в разделе «Знания», вещи, одолженное и места хранения. Некоторые операции через MCP пока ограничены, например запись контактных сведений: телефонов, дней рождения и заметок о контакте. Эти сведения можно вести прямо в Monica."],
                ['q' => "Как Monica ищет в моей личной памяти?", 'a' => "Ассистенты могут использовать поиск по ключевым словам в поддерживаемых записях, находить заметки и списки, просматривать и фильтровать другие сведения. Семантического или векторного поиска в Monica нет. Какие инструменты и слова для поиска использовать, решает ассистент."],
                ['q' => "Что такое MCP-сервер ИИ-памяти?", 'a' => "MCP-сервер предоставляет инструменты, которые могут вызывать совместимые ИИ-ассистенты. Удалённый MCP-сервер Monica позволяет ассистентам читать и записывать поддерживаемые личные записи, так что Monica может служить постоянной личной памятью вне самого ассистента."],
                ['q' => "Можно ли пользоваться Monica без ИИ?", 'a' => "Да. Monica это самостоятельное приложение для управления личными сведениями. Вы можете создавать, просматривать, изменять и упорядочивать записи напрямую, не подключая ассистента."],
                ['q' => "Можно ли развернуть свою ИИ-память у себя?", 'a' => "Да. Monica распространяется с открытым кодом по лицензии AGPL-3.0 и может работать на вашей инфраструктуре через Docker. MCP-сервер доступен и на экземплярах у себя. Защита и обслуживание собственного развёртывания лежат на вас."],
                ['q' => "Monica использует мои личные сведения для обучения моделей ИИ?", 'a' => "Monica не запускает и не обучает модели ИИ. Когда подключённый ассистент получает сведения, они передаются ассистенту. Дальше действуют правила конфиденциальности, хранения и обучения его сервиса."],
                ['q' => "Можно ли управлять тем, к каким сведениям у ассистента есть доступ?", 'a' => "Каждое подключение ассистента можно отозвать отдельно. Поля, помеченные как конфиденциальные, скрыты от ассистентов, подключённых через вход по OAuth. В остальном у подключений, как правило, доступ ко всему аккаунту: доступ по хранилищам и только для чтения пока не поддерживается."],
                ['q' => "Можно ли экспортировать мою личную память?", 'a' => "Monica поддерживает экспорт аккаунта и хранилища в JSON и экспорт отдельных контактов в Markdown. Записи раздела «Знания» и вещи пока не входят в JSON-экспорт аккаунта или хранилища."],
                ['q' => "ИИ-память Monica бесплатна?", 'a' => "Доступ по MCP входит в бесплатные облачные аккаунты с учётом обычных ограничений бесплатного тарифа. На экземплярах у себя Monica не вводит ограничений по тарифу. У сервиса ИИ-ассистента могут быть собственные требования к подписке или лимиты."],
                ['q' => "Что будет, если я сменю ИИ-ассистента?", 'a' => "Сведения, сохранённые в Monica, остаются в вашем аккаунте. Вы можете отключить прежнего ассистента и подключить другого совместимого, не перенося записи Monica в другую систему памяти."],
