                    ['text' => "Мы также используем Laravel Nightwatch, сервис компании Laravel Holdings Inc., чтобы следить за работой приложения, находить и диагностировать ошибки и проблемы с производительностью. Nightwatch обрабатывает эти данные по нашему поручению. Он получает техническую информацию о запросах к Monica (ваш IP-адрес, заголовки HTTP и пользовательский агент вашего браузера), идентификатор вашего аккаунта, а также тему и получателя уведомлений, которые мы отправляем. Он идентифицирует вас по идентификатору аккаунта, а не по имени. Мы опираемся на наш законный интерес в том, чтобы сервис был безопасным и хорошо работал: выявлять ошибки, диагностировать сбои и повышать производительность. Эти данные хранятся в Соединённых Штатах и удаляются через 30 дней."],
