                    ['text' => "Для приёма платежей за доступ к платной версии мы используем Stripe. Мы не храним на своих серверах данные кредитных карт и ничего, что касается самих транзакций. Однако, как это устроено в используемой нами для обработки платежей библиотеке с открытым исходным кодом (Laravel Cashier), мы храним последние 4 цифры кредитной карты и название платёжной системы (VISA или MasterCard). В Stripe вы как пользователь идентифицируетесь случайным номером, который они создают и используют."],
                    ['text' => "Что касается платежей, вы можете перейти на более низкий тариф или отменить подписку, когда пожелаете, а также удалить свой аккаунт. Когда вы отмените подписку, данные в Stripe обновятся автоматически, и у нас не будет возможности списать с вас деньги снова, даже если бы мы этого захотели. Чем меньше мы имеем дело с платёжной информацией, тем спокойнее нам."],
