                    ['text' => "Когда вы закрываете аккаунт, мы сразу же удаляем всю вашу персональную информацию из рабочей базы данных, но ваша информация остаётся в резервных копиях, которые мы храним 30 дней. По истечении 30 дней ваша информация будет полностью уничтожена. Хотя это находится под вашим контролем, мы можем удалить аккаунт за вас, если вы нас об этом попросите."],
